package org.beckenburg;
import dev.mrcalzon.water.*;
import dev.mrcalzon.weather.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.io.*;
import java.util.*;
import java.util.List;

/** Water authoring dock: portable plan handles and the actual map renderer
 * consume the same immutable document. Existing map geometry is preserved. */
public final class EnvironmentModuleEditor extends JPanel {
 private record Choice(String id,String title,HouseMap.Site site){public String toString(){return title;}}
 private final JFrame window;private final JComboBox<Choice> maps=new JComboBox<>();private final Map<String,WaterEditorModel> models=new LinkedHashMap<>();private final WaterGamePreview preview=new WaterGamePreview();private final JLabel status=new JLabel("Water module editor");
 private final SoundVolumeEditor sounds;
 private final WaterEditorPanel inspector;private final WaterCanvas canvas;private Choice choice;private WaterEditorModel current;private Runnable unlisten=()->{};
 public static JFrame open(Window parent,String level){var frame=new JFrame("Beckenburg — Water, Weather & Sound Module Editor");var panel=new EnvironmentModuleEditor(frame,level);frame.setContentPane(panel);frame.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);frame.setSize(1440,940);frame.setMinimumSize(new Dimension(1000,700));frame.setLocationRelativeTo(parent);frame.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){panel.close();}});frame.setVisible(true);return frame;}
 private EnvironmentModuleEditor(JFrame frame,String initial){super(new BorderLayout(5,5));window=frame;setBorder(BorderFactory.createEmptyBorder(5,5,5,5));current=new WaterEditorModel(new WaterDocument("loading",List.of()));
  inspector=new WaterEditorPanel(current,()->{var p=canvasCentre();return new WaterEditorPanel.Origin(p.x(),surfaceY(),p.z());},this::save);canvas=new WaterCanvas(current,inspector::snappingEnabled,inspector::angleSnappingEnabled,this::surfaceY);inspector.texturePicker(key->importTexture());
  var toolbar=new JPanel(new FlowLayout(FlowLayout.LEFT,5,2));toolbar.add(new JLabel("MAP"));maps.addItem(new Choice("castle","Castle Beckenburg",null));for(var site:HouseMap.Site.values()){var level=LevelPlans.build(site);maps.addItem(new Choice(level.id(),level.title(),site));}toolbar.add(maps);var focus=new JButton("Preview selected water");focus.addActionListener(e->{if(!current.selected().isEmpty())preview.focus(current.selected().get(0));});toolbar.add(focus);var export=new JButton("Export runtime bundle");export.addActionListener(e->export());toolbar.add(export);toolbar.add(new JLabel("Plan handles above · actual game view below"));add(toolbar,BorderLayout.NORTH);
  sounds=new SoundVolumeEditor(()->{var p=canvasCentre();return new double[]{p.x(),surfaceY()+2,p.z()};},preview::sounds,v->preview.focus(new WaterPlacement(v.id(),v.x(),v.y(),v.z(),v.width(),v.depth(),0,new WaterSettings())));preview.listener(sounds::listener);
  var views=new JSplitPane(JSplitPane.VERTICAL_SPLIT,canvas,preview);views.setResizeWeight(.52);views.setContinuousLayout(true);var tabs=new JTabbedPane();tabs.addTab("Water",inspector);tabs.addTab("Weather preview",weather());tabs.addTab("Sound volumes",sounds);tabs.setPreferredSize(new Dimension(450,700));var split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,views,tabs);split.setResizeWeight(1);split.setContinuousLayout(true);add(split,BorderLayout.CENTER);add(status,BorderLayout.SOUTH);
  getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(KeyStroke.getKeyStroke("control S"),"save-water");getActionMap().put("save-water",new AbstractAction(){public void actionPerformed(ActionEvent e){save();}});getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(KeyStroke.getKeyStroke("control Z"),"undo-water");getActionMap().put("undo-water",new AbstractAction(){public void actionPerformed(ActionEvent e){current.undo();}});getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(KeyStroke.getKeyStroke("control Y"),"redo-water");getActionMap().put("redo-water",new AbstractAction(){public void actionPerformed(ActionEvent e){current.redo();}});
  maps.addActionListener(e->choose((Choice)maps.getSelectedItem()));Choice selected=maps.getItemAt(0);for(int i=0;i<maps.getItemCount();i++)if(maps.getItemAt(i).id.equals(initial))selected=maps.getItemAt(i);maps.setSelectedItem(selected);if(choice==null)choose(selected);
 }
 private dev.mrcalzon.water.WaterModule.Point canvasCentre(){return canvas==null?new dev.mrcalzon.water.WaterModule.Point(0,0):canvas.centre();}
 private double surfaceY(){if(current==null||current.selected().isEmpty())return choice!=null&&choice.id.equals("hollow-creek")?-1.95:.15;return current.selected().get(0).y();}
 private void choose(Choice selected){if(selected==null)return;try{unlisten.run();var model=models.computeIfAbsent(selected.id,id->new WaterEditorModel(WorldWater.load(id)));model.validator(WorldWater::build);HouseMap map=selected.site==null?null:new HouseMap(selected.site);CastleHubMap castle=map==null?new CastleHubMap():null;WaterGamePreview.Camera camera;
  if(selected.id.equals("hollow-creek"))camera=new WaterGamePreview.Camera(34,.105,5,Math.atan2(-4,-8),-.225);else if(map!=null){var p=map.spawn(12);camera=new WaterGamePreview.Camera(p.x(),p.y()+1.62,p.z(),Math.atan2(map.centerX(0)-p.x(),map.centerZ(0)-p.z()),-.25);}else{var p=CastleLevelEdits.current().spawn();camera=new WaterGamePreview.Camera(p[0],1.62,p[1],p[2],-.3);}
  choice=selected;current=model;sounds.map(selected.id);inspector.setModel(model);canvas.setModel(model);preview.map(map,castle,camera,WorldWater.build(model.document()));final String[] revision={model.document().revision()};unlisten=model.listen(()->{String next=model.document().revision();if(!revision[0].equals(next)){preview.water(WorldWater.build(model.document()));revision[0]=next;}});if(!model.document().placements().isEmpty()){model.select(List.of(model.document().placements().get(0).id()));canvas.fit();}else canvas.centre(camera.x(),camera.z());status.setText(selected.title+" · water layout · Ctrl+S save · reload a playable map to activate a saved revision");
 }catch(RuntimeException error){status.setText("Cannot open map: "+error.getMessage());}}
 private JPanel weather(){var panel=new JPanel(new BorderLayout(4,4));var fields=new JPanel(new GridLayout(0,2,4,6));var type=new JComboBox<>(WeatherType.values());var hour=spin(20.64,0,23.99,.25);var temperature=spin(12,-50,50,1);var wind=spin(1,0,60,.5);var heading=spin(0,0,360,5);var clock=new JCheckBox("Run day cycle");final int[] revision={0};fields.add(new JLabel("Weather type"));fields.add(type);fields.add(new JLabel("Hour"));fields.add(hour);fields.add(new JLabel("Temperature °C"));fields.add(temperature);fields.add(new JLabel("Wind m/s"));fields.add(wind);fields.add(new JLabel("Wind heading °"));fields.add(heading);fields.add(clock);fields.add(new JLabel(""));Runnable update=()->preview.weather(new WaterGamePreview.Weather((WeatherType)type.getSelectedItem(),value(hour),value(temperature),value(wind),value(heading),clock.isSelected(),++revision[0]));type.addActionListener(e->{if(((WeatherType)type.getSelectedItem()).snow>0&&value(temperature)>0)temperature.setValue(-6.);update.run();});for(var s:new JSpinner[]{hour,temperature,wind,heading})s.addChangeListener(e->update.run());clock.addActionListener(e->update.run());panel.add(fields,BorderLayout.NORTH);var notes=new JTextArea("These controls preview the actual weather module. Mission weather remains host controlled.\n\nSky, precipitation meshes, wind and lightning are implemented. GPU ground wetness/snow coating remains a recorded integration item.\n\nWater gameplay boundaries remain part of each map's collision review.");notes.setLineWrap(true);notes.setWrapStyleWord(true);notes.setEditable(false);panel.add(notes,BorderLayout.CENTER);return panel;}
 private static JSpinner spin(double v,double lo,double hi,double step){return new JSpinner(new SpinnerNumberModel(v,lo,hi,step));}private static double value(JSpinner s){return ((Number)s.getValue()).doubleValue();}
 private String importTexture(){var chooser=new JFileChooser();chooser.setDialogTitle("Choose water texture sheet (PNG)");chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("PNG texture sheets","png"));if(chooser.showOpenDialog(window)!=JFileChooser.APPROVE_OPTION)return null;try{return WorldWater.importTexture(chooser.getSelectedFile().toPath());}catch(IOException e){throw new IllegalArgumentException(e.getMessage(),e);}}
 private void save(){try{WorldWater.save(current.document());current.markSaved();status.setText("Saved "+WorldWater.path(choice.id)+" · runtime map reload uses the new revision");}catch(IOException e){status.setText("Save failed: "+e.getMessage());}}
 private void export(){var chooser=new JFileChooser();chooser.setDialogTitle("Export runtime asset folder");chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showSaveDialog(window)!=JFileChooser.APPROVE_OPTION)return;try{Path root=chooser.getSelectedFile().toPath().toAbsolutePath().normalize();current.document().save(root.resolve("water").resolve(choice.id+".water"));var done=new HashSet<String>();for(var p:current.document().placements())for(String key:List.of("layer1.texture","layer2.texture")){String uri=p.settings().text(key);if(!uri.startsWith("assets://")||!done.add(uri))continue;String relative=uri.substring("assets://".length());Path target=root.resolve(relative).normalize();if(!target.startsWith(root))throw new IOException("Unsafe exported asset path");Files.createDirectories(target.getParent());Path source=WorldWater.assets().resolve(relative);if(Files.isRegularFile(source))Files.copy(source,target,StandardCopyOption.REPLACE_EXISTING);else try(var in=WorldWater.class.getResourceAsStream("/org/beckenburg/"+relative)){if(in==null)throw new IOException("Missing water sheet "+uri);Files.copy(in,target,StandardCopyOption.REPLACE_EXISTING);}}status.setText("Exported module layout and referenced texture sheets to "+root);}catch(IOException e){status.setText("Export failed: "+e.getMessage());}}
 private void close(){if(sounds.dirty()||models.values().stream().anyMatch(WaterEditorModel::dirty)){int answer=JOptionPane.showConfirmDialog(window,"Save modified water and sound layouts before closing?","Water modules",JOptionPane.YES_NO_CANCEL_OPTION);if(answer==JOptionPane.CANCEL_OPTION||answer==JOptionPane.CLOSED_OPTION)return;if(answer==JOptionPane.YES_OPTION)try{sounds.saveAll();for(var model:models.values())if(model.dirty()){WorldWater.save(model.document());model.markSaved();}}catch(IOException e){status.setText("Save failed: "+e.getMessage());return;}}preview.close();sounds.close();window.dispose();}
}
